                {
                    "code": "descr",
                    "value": null,
                    "values": {
                        "it": "Il 21 ottobre I° appuntamento intitolato “La morte e la sua musa”. Dalle ore 10 Mauro Dadea guiderà i visitatori attraverso un itinerario scandito da monumenti funebri con epigrafi scritte in poesia."
                    },
                    "elements": [],
                    "compositeelements": [],
                    "listelements": {}
                },
                {
                    "code": "data",
                    "value": "2023-10-18 00:00:00",
                    "values": {},
                    "elements": [],
                    "compositeelements": [],
