                {
                    "code": "descr",
                    "value": null,
                    "values": {
                        "it": "Organizzata dalla Scuola Civica di Musica di Sample City, le lezioni si terranno il 25 e 26 novembre presso la sede della scuola in via Venezia a Sample City"
                    },
                    "elements": [],
                    "compositeelements": [],
                    "listelements": {}
                },
                {
                    "code": "data",
                    "value": "2022-11-12 00:00:00",
                    "values": {},
                    "elements": [],
