                    "code": "descr",
                    "value": null,
                    "values": {
                        "it": "Intera giornata dedicata alle escursioni, all'arte, alle passeggiate naturalistiche, laboratori, allestimento di aiuole e tanto altro al Parco della Musica."
                    },
                    "elements": [],
