                    "code": "descr",
                    "value": null,
                    "values": {
                        "it": "Alle 18 musica, arte e natura si incontrano per una serata alla riscoperta di uno dei luoghi della cultura più amati della città."
                    },
                    "elements": [],
                    "compositeelements": [],
                    "listelements": {}
                },
                {
                    "code": "data_pubb",
                    "value": "2020-12-09 00:00:00",
