                {
                    "code": "descr",
                    "value": null,
                    "values": {
                        "it": "Anche in questa nuova tappa, in programma escursioni con reading multimediale, piantumazioni di nuovi alberi e aiuole, e la presenza dei nostri amici a quattro zampe."
                    },
                    "elements": [],
                    "compositeelements": [],
